CHECKIN_Qs = [{'id': 'executive_output', 'label': 'Executive Output', 'type': 'scale', 'max': 10, 'hint': 'Your prefrontal system performed at ___ out of 10 capacity today.'}, {'id': 'motor_precision', 'label': 'Motor Precision', 'type': 'scale', 'max': 10, 'hint': 'Your body executed the movement demands at ___ out of 10.'}, {'id': 'dual_task_load', 'label': 'Dual-Task Load Felt', 'type': 'scale', 'max': 10, 'hint': 'Cognitive-motor integration challenge level: 1=effortless, 10=at the edge.'}, {'id': 'resets', 'label': 'Cognitive Resets', 'type': 'number', 'hint': 'How many times did you stop to reset a drill? (These are data points, not failures.)'}, {'id': 'breakthrough', 'label': 'Breakthrough Moment', 'type': 'select', 'options': ['Prime / Fibonacci', 'Stroop / Color Reversal', 'N-Back Protocol', 'Spatial Matrix', 'Memory Wall', 'Tactical Scenario', 'Emotion-Under-Load', 'None today'], 'hint': "Which drill did you feel an 'unlock' or new capacity emerge?"}, {'id': 'state', 'label': 'Post-Session State', 'type': 'select', 'options': ['Energized + sharp', 'Tired but clear', 'Neutral', 'Fatigued', 'Overtrained signal'], 'hint': 'Your body and mind are reporting:'}, {'id': 'next_order', 'label': 'Next Session Order', 'type': 'text', 'hint': 'Issue yourself one specific technical directive for your next session. Present tense. Concrete.'}]


_QUESTIONS = {q["id"]: q for q in CHECKIN_Qs}
_NUMERIC_TYPES = ("scale", "number")


def phase_for_session_count(session_count: int) -> dict:
    """Phase projection for a completed-session count (A2 rule:
    floor(count / 12), capped at the final phase)."""
    if isinstance(session_count, bool) or \
            not isinstance(session_count, int):
        raise ValueError("session_count must be an integer")
    if session_count < 0:
        raise ValueError("session_count must be >= 0")
    idx = min(session_count // SESSIONS_PER_PHASE, len(PHASES) - 1)
    phase = PHASES[idx]
    return {
        "phase_index": idx,
        "phase_id": phase["id"],
        "label": phase["label"],
        "range": phase["range"],
        "macro": phase["macro"],
        "duration_minutes": phase["duration"],
        "sessions_per_week": phase["sessions"],
        "intensity": phase["intensity"],
        "focus": list(phase["focus"]),
        "nback": phase["nback"],
        "session_count": session_count,
        "sessions_into_phase": session_count - idx * SESSIONS_PER_PHASE,
        "sessions_per_phase": SESSIONS_PER_PHASE,
    }


def _default_next_order(phase_index: int) -> str:
    phase = PHASES[phase_index]
    return f"Next session: {phase['nback']}. {phase['nbackNote']}"


def validate_checkin(answers) -> dict:
    """Validate one typed check-in against CHECKIN_Qs. Every
    question is required (no empty-loggable check-ins); unknown
    fields are refused. Returns the normalized answers in
    question order. Raises ValueError before any state change."""
    if not isinstance(answers, dict):
        raise ValueError("check-in answers must be an object")
    unknown = sorted(set(answers) - set(_QUESTIONS))
    if unknown:
        raise ValueError(
            f"unknown check-in fields: {', '.join(unknown)}")
    missing = [q["id"] for q in CHECKIN_Qs if q["id"] not in answers]
    if missing:
        raise ValueError(
            f"missing required check-in fields: {', '.join(missing)}")
    normalized = {}
    for q in CHECKIN_Qs:
        qid, value = q["id"], answers[q["id"]]
        if q["type"] == "scale":
            if isinstance(value, bool) or \
                    not isinstance(value, (int, float)):
                raise ValueError(f"{qid} must be a number")
            if not 0 <= value <= q.get("max", 10):
                raise ValueError(
                    f"{qid} must be within 0..{q.get('max', 10)}")
        elif q["type"] == "number":
            if isinstance(value, bool) or \
                    not isinstance(value, (int, float)) \
                    or int(value) != value:
                raise ValueError(f"{qid} must be a whole number")
            if value < 0:
                raise ValueError(f"{qid} must be >= 0")
            value = int(value)
        elif q["type"] == "select":
            if value not in q["options"]:
                raise ValueError(
                    f"{qid} must be one of: {', '.join(q['options'])}")
        elif q["type"] == "text":
            if not isinstance(value, str) or not value.strip():
                raise ValueError(f"{qid} must be a non-empty directive")
            value = value.strip()
        normalized[qid] = value
    return normalized


def checkin_stats(checkins: list) -> dict:
    """Per-question stats over the entries that CARRY each value:
    a partial entry never drags an average toward zero."""
    stats = {"total_checkins": len(checkins)}
    for q in CHECKIN_Qs:
        if q["type"] not in _NUMERIC_TYPES:
            continue
        values = [e[q["id"]] for e in checkins
                  if isinstance(e.get(q["id"]), (int, float))
                  and not isinstance(e.get(q["id"]), bool)]
        stats[q["id"]] = {
            "count": len(values),
            "average": (round(sum(values) / len(values), 2)
                        if values else None),
        }
    return stats


def cogfit_state(checkins=None) -> dict:
    """The core-owned cognitive-fitness state block: typed
    check-in history, the session-count phase projection, the
    next_order directive and drag-free stats."""
    entries = copy.deepcopy(list(checkins or []))
    projection = phase_for_session_count(len(entries))
    if entries:
        next_order = entries[-1]["next_order"]
    else:
        next_order = _default_next_order(projection["phase_index"])
    return {
        "checkins": entries,
        "session_count": len(entries),
        "phase": projection,
        "next_order": next_order,
        "stats": checkin_stats(entries),
    }


def record_checkin(state: dict, answers, *,
                   timestamp: str | None = None) -> dict:
    """Append one typed check-in to a cogfit state block and
    return the rebuilt block (phase + next_order + stats follow
    the history). Validation runs first: a refused check-in
    changes nothing."""
    normalized = validate_checkin(answers)
    entries = list((state or {}).get("checkins") or [])
    entry = {
        "session": len(entries) + 1,
        "date": timestamp or datetime.now(timezone.utc).strftime(
            "%Y-%m-%dT%H:%M:%SZ"),
        **normalized,
    }
    return cogfit_state(entries + [entry])
